//! Predicate-bound deletion generated by pull rather than application SQL.
use super::{sql, Names, Table};
use crate::database::introspection::Column;

/// Emits filtered deletion for tables, rejecting an empty filter before execution.
/// Views never receive mutation operations. NULL predicates remain explicit.
/// Accepts caller-owned connections so sequence replacement remains transactional.
/// # Examples
/// ```sh
/// rustyroad pull --language rust --out ./generated-db
/// ```
pub(super) fn render(table: &Table, names: &Names, columns: &[&Column], bindings: &str) -> String {
    if table.view || columns.is_empty() {
        return String::new();
    }
    let function = names.function(table, "filter_delete");
    let filter = names.filter(table);
    let present = columns
        .iter()
        .map(|column| format!("filter.{}.is_some()", names.field(table, &column.name)))
        .collect::<Vec<_>>()
        .join(" || ");
    let prefix = format!("DELETE FROM {} WHERE TRUE", sql(&table.name));
    format!(
        "/// Deletes rows matching explicit equality predicates, returning the affected count.\n\
         /// Empty filters fail before database access; nullable Some(None) means IS NULL.\n\
         /// Example: `{function}(&mut *transaction, filter).await?`; does not commit.\n\
         pub async fn {function}<'e>(executor: impl sqlx::Executor<'e, Database = sqlx::Postgres>, filter: {filter}) -> Result<u64, sqlx::Error> {{\n\
             if !({present}) {{\n\
                 return Err(sqlx::Error::Protocol(\"Filtered deletion requires a predicate\".into()));\n\
             }}\n\
             let mut query = QueryBuilder::<Postgres>::new({prefix:?});\n\
             {bindings}\n\
             Ok(query.build().execute(executor).await?.rows_affected())\n\
         }}\n\n"
    )
}
